from pathlib import Path
import re
r=Path.cwd()
repo=r/'G-safeguard-main/G-safeguard-main'
parts=[]
def put(s): parts.append(s)
def link(f,n): return f'[{f}:{n}](<{(repo/f).as_posix()}:{n}>)'
def code(f,a,b,notes):
    ls=(repo/f).read_text(encoding='utf-8').splitlines()
    rows=[(i,ls[i-1]) for i in range(a,b+1) if ls[i-1].strip()]
    assert len(rows)==len(notes),(f,a,len(rows),len(notes))
    put(f'**代码文件及起始行：{link(f,a)}，范围 {a}–{b} 行。**')
    put('```python\n'+'\n'.join(f'{i:3} | {s}' for i,s in rows)+'\n```')
    put('**逐行中文解释：**\n\n'+'\n'.join(f'- **第 {i} 行**：{t}' for (i,_),t in zip(rows,notes)))
def sec(n,title,eq,page,status,summary,variables):
    put(f'## 公式 ({n})：{title}')
    put(f'**论文位置：PDF 第 {page} 页，印刷页 {7260+page}。**\n\n$$\n{eq}\n$$')
    put('**对应程度：**'+status)
    put('**一句话说明输入、输出、执行过程和核心功能：**'+summary)
    put('**变量的自然语言解释：**'+variables)
